const importStylePackImagesToCanvas=useCallback(async(urls:string[])=>{
  const cleanUrls=normalizeReferenceUrls(urls,48).urls;
  if(cleanUrls.length===0)return;
  const effectiveProjectId=await ensureProject();
  if(!effectiveProjectId){
    setActionToast("没有项目，无法导入到画布");
    setTimeout(()=>setActionToast(null),2200);
    return;
  }
  pushUndoHistory();
  const importedImages:CanvasImage[]=[];
  let successCount=0;
  let failCount=0;
  for(const [index,sourceUrl] of cleanUrls.entries()){
    try{
      const fallbackName="style-pack-" + Date.now() + "-" + (index + 1) + ".png";
      const sourceResponse=sourceUrl.startsWith("data:")||sourceUrl.startsWith("blob:")
        ? await fetch(sourceUrl)
        : await fetch("/api/download-image?url=" + encodeURIComponent(sourceUrl) + "&filename=" + encodeURIComponent(fallbackName) + "&t=" + Date.now(),{cache:"no-store"});
      if(!sourceResponse.ok)throw new Error("读取图片失败");
      const blob=await sourceResponse.blob();
      const mimeType=blob.type||"image/png";
      const ext=mimeType.includes("jpeg")?"jpg":mimeType.includes("webp")?"webp":mimeType.includes("gif")?"gif":"png";
      const fileName=fallbackName.replace(/\.[^.]+$/,"." + ext);
      const file=new File([blob],fileName,{type:mimeType});
      const objectUrl=URL.createObjectURL(file);
      const naturalSize=await new Promise<{w:number;h:number;}>(resolve=>{
        const img=new Image();
        img.onload=()=>{
          resolve({w:img.naturalWidth||320,h:img.naturalHeight||320});
          URL.revokeObjectURL(objectUrl);
        };
        img.onerror=()=>{
          resolve({w:320,h:320});
          URL.revokeObjectURL(objectUrl);
        };
        img.src=objectUrl;
      });
      const aspect=naturalSize.w/naturalSize.h||1;
      const displayW=320;
      const displayH=Math.max(1,Math.round(displayW/(Number.isFinite(aspect)&&aspect>0?aspect:1)));
      const uploadFormData=new FormData();
      uploadFormData.append("file",file);
      uploadFormData.append("projectId",effectiveProjectId);
      const uploadRes=await fetch("/api/upload",{method:"POST",headers:getAuthHeaders(),body:uploadFormData});
      const uploadData=await uploadRes.json().catch(()=>({}));
      if(!uploadRes.ok||!uploadData.url)throw new Error(uploadData.error||"上传失败");
      const clusterPos=getImageClusterPosition(displayW,displayH);
      const pos=findNonOverlappingPosition(clusterPos.x,clusterPos.y,displayW,displayH);
      const now=new Date().toISOString();
      const newImage:CanvasImage={
        id:"style-import-" + Date.now() + "-" + index + "-" + Math.random().toString(36).slice(2,6),
        project_id:effectiveProjectId,
        prompt:"从风格包导入",
        image_url:uploadData.url,
        image_key:uploadData.key||null,
        reference_images:null,
        canvas_x:pos.x,
        canvas_y:pos.y,
        canvas_width:displayW,
        canvas_height:displayH,
        size:Math.max(0.1,aspect).toFixed(2)+":1",
        model:"style-pack",
        status:"completed",
        is_favorite:false,
        is_reference:false,
        created_at:now,
        updated_at:now,
      };
      setCanvasImages(prev=>[newImage,...prev]);
      canvasImagesRef.current=[newImage,...canvasImagesRef.current];
      fetch("/api/history",{method:"POST",headers:{"Content-Type":"application/json",...getAuthHeaders()},body:JSON.stringify({id:newImage.id,projectId:effectiveProjectId,prompt:newImage.prompt,imageUrl:newImage.image_url,imageKey:newImage.image_key||"",size:newImage.size,model:newImage.model,referenceImages:[sourceUrl],canvasX:newImage.canvas_x,canvasY:newImage.canvas_y,canvasWidth:newImage.canvas_width,canvasHeight:newImage.canvas_height})}).catch(()=>{});
      importedImages.push(newImage);
      successCount+=1;
    }catch(err){
      failCount+=1;
    }
  }
  if(importedImages.length>0){
    const minX=Math.min(...importedImages.map(img=>img.canvas_x));
    const minY=Math.min(...importedImages.map(img=>img.canvas_y));
    const maxX=Math.max(...importedImages.map(img=>img.canvas_x+img.canvas_width));
    const maxY=Math.max(...importedImages.map(img=>img.canvas_y+img.canvas_height));
    panCanvasToPosition(minX,minY,maxX-minX,maxY-minY);
    setSelectedImageId(importedImages[importedImages.length-1].id);
    setSelectedImageIds([importedImages[importedImages.length-1].id]);
    setActionToast(failCount>0?"已导入 " + successCount + " 张风格图，" + failCount + " 张失败":"已导入 " + successCount + " 张风格图到画布");
    setTimeout(()=>setActionToast(null),2400);
  }else{
    setActionToast("未能导入风格包图片");
    setTimeout(()=>setActionToast(null),2200);
  }
},[ensureProject,findNonOverlappingPosition,getAuthHeaders,getImageClusterPosition,panCanvasToPosition,pushUndoHistory]);
